{
  "packs": [
    {
      "id": "basics",
      "version": "60924.1"
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60924.1"
    },
    {
      "id": "git-github",
      "version": "60922.5",
      "via": [
        "basics"
      ]
    },
    {
