1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries, sessionTranscriptPaths } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	import { SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
7	import { isVersion } from '../../version.mjs';
