9	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
10	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
11	  if (r.status !== 0 && !allowFail) {
12	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
13	  }
14	  return r.status === 0 ? r.stdout : null;
15	}
16	
17	const git = (root, ...args) => sh(root, 'git', args);
18	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
19	
20	// The base branch this repo's work is judged against, in preference order.
21	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
22	// refs before a context is built at all — one list, so what CI fetches and what a
23	// context resolves can never name different branches.
24	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
25	
26	// All four candidates in ONE subprocess. `cat-file --batch-check` takes revisions on
27	// stdin and answers each independently — `<sha> commit <size>` for one that resolves,
28	// `<input> missing` for one that does not — so it is the same revision parser
29	// `rev-parse --verify` uses, `^{commit}` peeling included, asked four questions at
30	// once instead of four times. A repo whose base is a local `main` (every check fixture,
31	// and any clone without a remote) missed on both `origin/` candidates first and paid
32	// three spawns for an answer that now costs one.
33	function resolveBaseRef(root) {
34	  const answers = (sh(root, 'git', ['cat-file', '--batch-check'],
35	    { allowFail: true, input: `${BASE_REF_CANDIDATES.map((ref) => `${ref}^{commit}`).join('\n')}\n` }) || '')
36	    .split('\n');
37	  // Object-id length is the repo's hash algorithm's, not a constant — sha1 and sha256
38	  // repos both answer here, and only the `commit` word decides.
39	  return BASE_REF_CANDIDATES.find((_, i) => /^[0-9a-f]+ commit /.test(answers[i] ?? '')) ?? null;
40	}
41	
42	const FETCH_TIMEOUT_MS = 8000;
43	const FETCH_WINDOW_MS = 5 * 60_000;
44	
45	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
46	// clone freezes it at container-creation time — so every commit the base branch gained
47	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
48	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
49	// rule) report other people's commits as introduced by this change, and `--changed`
50	// widens to files the change never touched. Refreshing the ref once per run is what makes
51	// "the work" mean the work.
52	//
53	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
54	// fetch fails or times out and the run continues against the ref as it stands, exactly as
55	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
56	// no local branch, no index, no working tree, nothing the session could be surprised by.
57	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
58	//
59	// And it runs once per freshness window, not once per run: the Stop hook builds a context
60	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
61	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
62	// which ref was refreshed and when; a run inside the window trusts it and skips. The
63	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
64	// nothing about this base's freshness — and the staleness the window admits is the same
65	// class the fetch's own failure tolerance already accepts, now bounded by the window.
66	function refreshBaseRef(root, ref) {
67	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
68	  const m = /^([^/]+)\/(.+)$/.exec(ref);
69	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
70	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
71	  const marker = markerRel ? resolve(root, markerRel) : null;
72	  if (marker) {
73	    try {
74	      const last = JSON.parse(readFileSync(marker, 'utf8'));
75	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
76	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
77	  }
78	  const [, remote, branch] = m;
79	  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
80	    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
81	  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
82	  if (fetched !== null && marker) {
83	    try { writeFileSync(marker, JSON.stringify({ ref, at: Date.now() })); }
84	    catch { /* an unwritable git dir only costs the next run a fetch */ }
85	  }
86	}
87	
88	function lines(out) {
89	  return (out || '').split('\n').filter(Boolean);
90	}
91	
92	// The tracked and the untracked file list out of ONE subprocess. `-t` prefixes each
93	// path with its status tag, and under `-c -o` the only tag an untracked path can
94	// carry is `?` — a cached path is `H`, `S` while skip-worktree is set, or `M` per
95	// index stage while a merge is unresolved, which is the same one-line-per-stage
96	// shape plain `ls-files` prints. So the tag alone separates the two lists, each in
97	// git's own order and with its own `core.quotePath` quoting, exactly as the
98	// `ls-files` / `ls-files --others --exclude-standard` pair produced them.
99	function listFiles(root) {
100	  const tracked = [];
101	  const untracked = [];
102	  for (const line of lines(gitTry(root, 'ls-files', '-c', '-o', '--exclude-standard', '-t'))) {
103	    (line.startsWith('? ') ? untracked : tracked).push(line.slice(2));
104	  }
105	  return { tracked, untracked };
106	}
107	
108	// Both diff lists out of one subprocess where the answer is unambiguous. The pair
109	// this replaces asked the same diff twice — `--diff-filter=d` for the files the
110	// change touched, `--diff-filter=D` for the ones it removed — and `--name-status`
111	// labels every entry, so `D` is the second list and everything else is the first.
112	//
113	// A rename or copy is the one entry that does not name a single path — git reports
114	// it as `R<score>\t<source>\t<destination>`, where the pair named the destination
115	// alone — so a change carrying one falls back to the pair. Reading the last field
116	// gives the same set, and git 2.43 orders that entry where the pair's output has it
117	// (fuzzed over 200 random histories of renames, deletions, additions and edits);
118	// but nothing git documents says the two commands order a two-path entry alike, and
119	// this list's order reaches ctx.files. A second subprocess on the rare change that
120	// renames something is cheaper than depending on that.
121	function diffLists(root, diffBase, mergeBase) {
122	  const status = gitTry(root, 'diff', '--name-status', diffBase);
123	  const entries = lines(status).map((l) => l.split('\t'));
124	  if (status !== null && !entries.some(([s]) => s.startsWith('R') || s.startsWith('C'))) {
125	    return {
126	      vsBase: entries.filter(([s]) => !s.startsWith('D')).map((e) => e[e.length - 1]),
127	      deleted: mergeBase ? entries.filter(([s]) => s.startsWith('D')).map((e) => e[1]) : [],
128	    };
129	  }
130	  return {
131	    vsBase: lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase)),
132	    deleted: mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [],
133	  };
134	}
135	
136	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
137	// .gitattributes) — third-party or machine-written content, not the project's own
138	// code. `buildContext` drops these from the default `ctx.files`, so every check that
139	// reasons about "the project's code" skips them for free: a suppression marker inside
140	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
141	// link in a vendored doc are none of them the project's decision. `git check-attr`
142	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
143	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
144	// check that reasons *about* generated files (generated-merge-driver).
145	function vendoredSet(root, files) {
146	  const set = new Set();
147	  if (!files.length) return set;
148	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
149	    { allowFail: true, input: files.join('\n') + '\n' });
150	  for (const line of (out || '').split('\n')) {
151	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
152	    if (m && m[2] === 'set') set.add(m[1]);
153	  }
154	  return set;
155	}
156	
157	// The complete set of top-level settings the settings file may carry. A key
158	// outside this set is a typo or a stale name — a settings error as real as invalid
159	// JSON, caught at load so it can't silently change nothing. Per-pack parameters
160	// live on that pack's own `packs` entry as `config`; the top-level `packConfig` key
161	// they came from was folded by the `pack-entry-config` migration record
162	// (engine/migrations/) and stopped being read on #1640's window, so a straggler now
163	// gets that unknown-setting error.
164	// `engineVersion` is the engine version this repo's mount holds, written by the
165	// update flows; a pack's installed version sits on that pack's own entry. Both were
166	// a nested `claudinite` block until #1252, alongside an `updated` datetime and a
167	// `ref` — those two held the provenance of the last FULL re-vendor rather than of
168	// this mount, so a member updating nightly read as months stale, and nothing may
169	// judge freshness by them any more because they no longer exist.
170	// `dailyClaudiniteUpdatesRequirePrReview` is the harsh override: true leaves this
171	// repo's daily update PR open for a human. Absent — the normal shape — means it
172	// lands on its own. It is an override rather than a materialized preference
173	// because every member wants the same thing, and the one that doesn't should have
174	// to say so (#1252).
175	// `taskScheduler` is where the vendored scheduler's own parameters are declared
176	// (docs/PRINCIPLES.md): which tasks this repo does not want instantiated, where its
177	// agentic phases are dispatched. Absence is legal and means the documented defaults.
178	// Nothing writes into a member's README any more, so there is no `badges` key here:
179	// a member carrying the stale one gets the unknown-setting error below, and the
180	// wiring converge clears it.
181	// There is no `dormant` key either. Dormancy is a property of the SCHEDULER, not of
182	// the repository — every effect it has is an effect on the work-item queue — so it is
183	// a parameter of the pack that owns that mechanism, declared on that pack's own entry,
184	// and the engine neither validates it nor normalizes it. A repo declaring no scheduler
185	// pack has none for the word to mean anything about.
186	// The retired `claudinite` and `maintenance` blocks are no longer read (#1640), and
187	// neither is the top-level `packConfig`: a member still carrying one now collects the
188	// unknown-setting error below, which is the settings-validity gate doing the
189	// enforcement the tolerance was standing in for.
190	export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants',
191	  'engineVersion', 'dailyClaudiniteUpdatesRequirePrReview', 'taskScheduler'];
192	
193	// Keys accepted on the way in and written by nothing. `dormant` was never the
194	// engine's to fold, and its reader lives in the pack that owns the scheduler. It is
195	// listed only so a member still declaring it at the top level collects no
196	// unknown-setting error while the migration record converges the fleet onto the pack
197	// entry.
198	// @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
199	export const LEGACY_CONFIG_KEYS = ['dormant'];
200	const KNOWN_CONFIG_KEYS = [...CONFIG_KEYS, ...LEGACY_CONFIG_KEYS];
201	
202	// The predicate this module used to own, kept ONLY for the pack-lane window. The engine
203	// and a pack reach a member on separate cycles, so every member spends a window holding
204	// this engine beside a pack version that still imports `isDormant` from here — and a
205	// missing export there is a crash mid-update, in the flow that would have delivered
206	// the fix.
207	//
208	// It reads the retired top-level key and nothing else, which is exactly right for the
209	// callers it exists for: a pack old enough to import it is old enough to predate the
210	// pack-entry spelling, so this answers the only question that code knows how to ask.
211	// It is NOT the definition — that is the tasks pack's, which resolves both spellings —
212	// and nothing new may call it.
213	//
214	// @deprecated Use the `isDormant` the scheduler's own pack publishes from its
215	// public surface, which is where the live definition lives.
216	// @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
217	export const isDormant = (config) => config?.dormant === true;
218	
219	// The keys a `schedule` object may carry.
220	const SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay', 'dispatch', 'agenticTaskInvocationEndpoints', 'disabledTasks'];
221	
222	// The per-repo scheduling anchor, retired (#1995). A cadence now measures whole UTC
223	// periods, and the scheduler workflow's own cron hours are derived from the repo name
224	// at scaffold, so nothing reads these three. They stay ACCEPTED rather than becoming
225	// unknown keys, because an unknown key is a blocking settings error and every member
226	// still carries them until its own update runs the record that strips them out;
227	// `legacy-shape-in-use` is the advisory that tells each holder, and #2181 takes them
228	// off SCHEDULE_KEYS once the record has had its window.
229	// @legacy-tolerance advisory:legacy-shape-in-use retire:#2181
230	export const RETIRED_SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay'];
231	
232	// What the endpoint map is called. `endpoints` said nothing about WHICH endpoints —
233	// a scheduler has several kinds it could mean — where these are exactly one thing:
234	// the routine URLs a task's agentic phase is invoked through (#1252).
235	export const ENDPOINTS_KEY = 'agenticTaskInvocationEndpoints';
236	
237	// The retired spelling, no longer read anywhere (#1640). It stays exported because a
238	// fielded pack version imports it by name, and an engine that reaches a member ahead
239	// of that pack must not fault it at link time; it comes out with the other lane
240	// shims (#1911).
241	// @legacy-tolerance advisory:none retire:#1911
242	export const LEGACY_ENDPOINTS_KEY = 'endpoints';
243	
244	// `taskScheduler.dispatch` chose between the slot scheduler and the work-item
245	// queue while the two coexisted (docs/PRINCIPLES.md). The slot scheduler is
246	// deleted (#974), so `queue` is the only mechanism and the key means nothing.
247	//
248	// It stays VALIDATED rather than merely ignored, and `"slots"` is now an error:
249	// a parameter that has stopped being read must fail loudly, because the one thing
250	// a member declaring `"slots"` must not get is the queue running silently under a
251	// declaration that says otherwise. Declaring `"queue"` is still accepted — it says
252	// what is true — and omitting it is the normal shape.
253	export const DISPATCH_MODES = ['queue'];
254	
255	// The properties a `packs` entry object may carry: the pack's parameters
256	// (`config`), its adoption-interview answers (`answers` — the owner's verbatim
257	// responses to the questions the pack declares on its pack.mjs, keyed by
258	// question id; read by the adoption skill's interview machinery), and the rule overrides / acceptances that
259	// exist BECAUSE this pack is declared (`rules`, `accept` — they may name any
260	// rule; the entry is their provenance). `via` is written by
261	// resolveDeclaredPacks on materialized dependencies (engine/pack_loader/pack-registry.mjs).
262	// `version` is the pack version this repo has INSTALLED — written by the update
263	// and install flows onto the entry of the pack it describes, which is the only
264	// place it cannot be orphaned from what it prices. It lived in a central
265	// `claudinite.packVersions` map until #1252, where a pack rename left a version
266	// keyed by a spelling no entry carried.
267	export const PACK_ENTRY_KEYS = ['id', 'version', 'config', 'answers', 'rules', 'accept', 'via'];
268	
269	// Load and validate the project's settings. Validity is checked at load — the
270	// moment Claudinite reads the file — and every problem is collected into `errors`
271	// (each `{ what, fix }`), the runner's single settings-validity gate. A wrong
272	// property name, malformed JSON, and a wrong pack name are all equally settings
273	// errors; unknown *pack* names need the registry, so the runner adds those (it
274	// holds the known-pack list). On unparsable/misshaped JSON the usable fields fall
275	// back to empty so the rest of a sweep still runs, with the error reported.
276	//
277	// The returned shape is NORMALIZED: `packs` is plain BARE ids (a local pack's
278	// namespaced `local/<id>` token resolves through packEntryId, so every
279	// downstream lookup — packEntries, the packConfig view — keys by the pack's
