import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { parseEntries, sessionTranscriptPaths } from './session-transcript.mjs';
import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
import { SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
import { isVersion } from '../../version.mjs';

function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
  if (r.status !== 0 && !allowFail) {
    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
  }
  return r.status === 0 ? r.stdout : null;
}

const git = (root, ...args) => sh(root, 'git', args);
const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });

// The base branch this repo's work is judged against, in preference order.
// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
// refs before a context is built at all — one list, so what CI fetches and what a
// context resolves can never name different branches.
export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];

// All four candidates in ONE subprocess. `cat-file --batch-check` takes revisions on
// stdin and answers each independently — `<sha> commit <size>` for one that resolves,
// `<input> missing` for one that does not — so it is the same revision parser
// `rev-parse --verify` uses, `^{commit}` peeling included, asked four questions at
// once instead of four times. A repo whose base is a local `main` (every check fixture,
// and any clone without a remote) missed on both `origin/` candidates first and paid
// three spawns for an answer that now costs one.
function resolveBaseRef(root) {
  const answers = (sh(root, 'git', ['cat-file', '--batch-check'],
    { allowFail: true, input: `${BASE_REF_CANDIDATES.map((ref) => `${ref}^{commit}`).join('\n')}\n` }) || '')
    .split('\n');
  // Object-id length is the repo's hash algorithm's, not a constant — sha1 and sha256
  // repos both answer here, and only the `commit` word decides.
  return BASE_REF_CANDIDATES.find((_, i) => /^[0-9a-f]+ commit /.test(answers[i] ?? '')) ?? null;
}

const FETCH_TIMEOUT_MS = 8000;
const FETCH_WINDOW_MS = 5 * 60_000;

// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
// clone freezes it at container-creation time — so every commit the base branch gained
// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
// rule) report other people's commits as introduced by this change, and `--changed`
// widens to files the change never touched. Refreshing the ref once per run is what makes
// "the work" mean the work.
//
// Best-effort by construction — no network, no remote, a lock held, a slow server: the
// fetch fails or times out and the run continues against the ref as it stands, exactly as
// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
// no local branch, no index, no working tree, nothing the session could be surprised by.
// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
//
// And it runs once per freshness window, not once per run: the Stop hook builds a context
// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
// which ref was refreshed and when; a run inside the window trusts it and skips. The
// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
// nothing about this base's freshness — and the staleness the window admits is the same
// class the fetch's own failure tolerance already accepts, now bounded by the window.
function refreshBaseRef(root, ref) {
  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
  const m = /^([^/]+)\/(.+)$/.exec(ref);
  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
  const marker = markerRel ? resolve(root, markerRel) : null;
  if (marker) {
    try {
      const last = JSON.parse(readFileSync(marker, 'utf8'));
      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
  }
  const [, remote, branch] = m;
  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
  if (fetched !== null && marker) {
    try { writeFileSync(marker, JSON.stringify({ ref, at: Date.now() })); }
    catch { /* an unwritable git dir only costs the next run a fetch */ }
  }
}

function lines(out) {
  return (out || '').split('\n').filter(Boolean);
}

// The tracked and the untracked file list out of ONE subprocess. `-t` prefixes each
// path with its status tag, and under `-c -o` the only tag an untracked path can
// carry is `?` — a cached path is `H`, `S` while skip-worktree is set, or `M` per
// index stage while a merge is unresolved, which is the same one-line-per-stage
// shape plain `ls-files` prints. So the tag alone separates the two lists, each in
// git's own order and with its own `core.quotePath` quoting, exactly as the
// `ls-files` / `ls-files --others --exclude-standard` pair produced them.
function listFiles(root) {
  const tracked = [];
  const untracked = [];
  for (const line of lines(gitTry(root, 'ls-files', '-c', '-o', '--exclude-standard', '-t'))) {
    (line.startsWith('? ') ? untracked : tracked).push(line.slice(2));
  }
  return { tracked, untracked };
}

// Both diff lists out of one subprocess where the answer is unambiguous. The pair
// this replaces asked the same diff twice — `--diff-filter=d` for the files the
// change touched, `--diff-filter=D` for the ones it removed — and `--name-status`
// labels every entry, so `D` is the second list and everything else is the first.
//
// A rename or copy is the one entry that does not name a single path — git reports
// it as `R<score>\t<source>\t<destination>`, where the pair named the destination
// alone — so a change carrying one falls back to the pair. Reading the last field
// gives the same set, and git 2.43 orders that entry where the pair's output has it
// (fuzzed over 200 random histories of renames, deletions, additions and edits);
// but nothing git documents says the two commands order a two-path entry alike, and
// this list's order reaches ctx.files. A second subprocess on the rare change that
// renames something is cheaper than depending on that.
function diffLists(root, diffBase, mergeBase) {
  const status = gitTry(root, 'diff', '--name-status', diffBase);
  const entries = lines(status).map((l) => l.split('\t'));
  if (status !== null && !entries.some(([s]) => s.startsWith('R') || s.startsWith('C'))) {
    return {
      vsBase: entries.filter(([s]) => !s.startsWith('D')).map((e) => e[e.length - 1]),
      deleted: mergeBase ? entries.filter(([s]) => s.startsWith('D')).map((e) => e[1]) : [],
    };
  }
  return {
    vsBase: lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase)),
    deleted: mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [],
  };
}

// Files git marks vendored or generated (linguist-vendored / linguist-generated in
// .gitattributes) — third-party or machine-written content, not the project's own
// code. `buildContext` drops these from the default `ctx.files`, so every check that
// reasons about "the project's code" skips them for free: a suppression marker inside
// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
// link in a vendored doc are none of them the project's decision. `git check-attr`
// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
// check that reasons *about* generated files (generated-merge-driver).
function vendoredSet(root, files) {
  const set = new Set();
  if (!files.length) return set;
  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
    { allowFail: true, input: files.join('\n') + '\n' });
  for (const line of (out || '').split('\n')) {
    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
    if (m && m[2] === 'set') set.add(m[1]);
  }
  return set;
}

// The complete set of top-level settings the settings file may carry. A key
// outside this set is a typo or a stale name — a settings error as real as invalid
// JSON, caught at load so it can't silently change nothing. Per-pack parameters
// live on that pack's own `packs` entry as `config`; the top-level `packConfig` key
// they came from was folded by the `pack-entry-config` migration record
// (engine/migrations/) and stopped being read on #1640's window, so a straggler now
// gets that unknown-setting error.
// `engineVersion` is the engine version this repo's mount holds, written by the
// update flows; a pack's installed version sits on that pack's own entry. Both were
// a nested `claudinite` block until #1252, alongside an `updated` datetime and a
// `ref` — those two held the provenance of the last FULL re-vendor rather than of
// this mount, so a member updating nightly read as months stale, and nothing may
// judge freshness by them any more because they no longer exist.
// `dailyClaudiniteUpdatesRequirePrReview` is the harsh override: true leaves this
// repo's daily update PR open for a human. Absent — the normal shape — means it
// lands on its own. It is an override rather than a materialized preference
// because every member wants the same thing, and the one that doesn't should have
// to say so (#1252).
// `taskScheduler` is where the vendored scheduler's own parameters are declared
// (docs/PRINCIPLES.md): which tasks this repo does not want instantiated, where its
// agentic phases are dispatched. Absence is legal and means the documented defaults.
// Nothing writes into a member's README any more, so there is no `badges` key here:
// a member carrying the stale one gets the unknown-setting error below, and the
// wiring converge clears it.
// There is no `dormant` key either. Dormancy is a property of the SCHEDULER, not of
// the repository — every effect it has is an effect on the work-item queue — so it is
// a parameter of the pack that owns that mechanism, declared on that pack's own entry,
// and the engine neither validates it nor normalizes it. A repo declaring no scheduler
// pack has none for the word to mean anything about.
// The retired `claudinite` and `maintenance` blocks are no longer read (#1640), and
// neither is the top-level `packConfig`: a member still carrying one now collects the
// unknown-setting error below, which is the settings-validity gate doing the
// enforcement the tolerance was standing in for.
export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants',
  'engineVersion', 'dailyClaudiniteUpdatesRequirePrReview', 'taskScheduler'];

// Keys accepted on the way in and written by nothing. `dormant` was never the
// engine's to fold, and its reader lives in the pack that owns the scheduler. It is
// listed only so a member still declaring it at the top level collects no
// unknown-setting error while the migration record converges the fleet onto the pack
// entry.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
export const LEGACY_CONFIG_KEYS = ['dormant'];
const KNOWN_CONFIG_KEYS = [...CONFIG_KEYS, ...LEGACY_CONFIG_KEYS];

// The predicate this module used to own, kept ONLY for the pack-lane window. The engine
// and a pack reach a member on separate cycles, so every member spends a window holding
// this engine beside a pack version that still imports `isDormant` from here — and a
// missing export there is a crash mid-update, in the flow that would have delivered
// the fix.
//
// It reads the retired top-level key and nothing else, which is exactly right for the
// callers it exists for: a pack old enough to import it is old enough to predate the
// pack-entry spelling, so this answers the only question that code knows how to ask.
// It is NOT the definition — that is the tasks pack's, which resolves both spellings —
// and nothing new may call it.
//
// @deprecated Use the `isDormant` the scheduler's own pack publishes from its
// public surface, which is where the live definition lives.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
export const isDormant = (config) => config?.dormant === true;

// The keys a `schedule` object may carry.
const SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay', 'dispatch', 'agenticTaskInvocationEndpoints', 'disabledTasks'];

// The per-repo scheduling anchor, retired (#1995). A cadence now measures whole UTC
// periods, and the scheduler workflow's own cron hours are derived from the repo name
// at scaffold, so nothing reads these three. They stay ACCEPTED rather than becoming
// unknown keys, because an unknown key is a blocking settings error and every member
// still carries them until its own update runs the record that strips them out;
// `legacy-shape-in-use` is the advisory that tells each holder, and #2181 takes them
// off SCHEDULE_KEYS once the record has had its window.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#2181
export const RETIRED_SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay'];

// What the endpoint map is called. `endpoints` said nothing about WHICH endpoints —
// a scheduler has several kinds it could mean — where these are exactly one thing:
// the routine URLs a task's agentic phase is invoked through (#1252).
export const ENDPOINTS_KEY = 'agenticTaskInvocationEndpoints';

// The retired spelling, no longer read anywhere (#1640). It stays exported because a
// fielded pack version imports it by name, and an engine that reaches a member ahead
// of that pack must not fault it at link time; it comes out with the other lane
// shims (#1911).
// @legacy-tolerance advisory:none retire:#1911
export const LEGACY_ENDPOINTS_KEY = 'endpoints';

// `taskScheduler.dispatch` chose between the slot scheduler and the work-item
// queue while the two coexisted (docs/PRINCIPLES.md). The slot scheduler is
// deleted (#974), so `queue` is the only mechanism and the key means nothing.
//
// It stays VALIDATED rather than merely ignored, and `"slots"` is now an error:
// a parameter that has stopped being read must fail loudly, because the one thing
// a member declaring `"slots"` must not get is the queue running silently under a
// declaration that says otherwise. Declaring `"queue"` is still accepted — it says
// what is true — and omitting it is the normal shape.
export const DISPATCH_MODES = ['queue'];

// The properties a `packs` entry object may carry: the pack's parameters
// (`config`), its adoption-interview answers (`answers` — the owner's verbatim
// responses to the questions the pack declares on its pack.mjs, keyed by
// question id; read by the adoption skill's interview machinery), and the rule overrides / acceptances that
// exist BECAUSE this pack is declared (`rules`, `accept` — they may name any
// rule; the entry is their provenance). `via` is written by
// resolveDeclaredPacks on materialized dependencies (engine/pack_loader/pack-registry.mjs).
// `version` is the pack version this repo has INSTALLED — written by the update
// and install flows onto the entry of the pack it describes, which is the only
// place it cannot be orphaned from what it prices. It lived in a central
// `claudinite.packVersions` map until #1252, where a pack rename left a version
// keyed by a spelling no entry carried.
export const PACK_ENTRY_KEYS = ['id', 'version', 'config', 'answers', 'rules', 'accept', 'via'];

// Load and validate the project's settings. Validity is checked at load — the
// moment Claudinite reads the file — and every problem is collected into `errors`
// (each `{ what, fix }`), the runner's single settings-validity gate. A wrong
// property name, malformed JSON, and a wrong pack name are all equally settings
// errors; unknown *pack* names need the registry, so the runner adds those (it
// holds the known-pack list). On unparsable/misshaped JSON the usable fields fall
// back to empty so the rest of a sweep still runs, with the error reported.
//
// The returned shape is NORMALIZED: `packs` is plain BARE ids (a local pack's
// namespaced `local/<id>` token resolves through packEntryId, so every
// downstream lookup — packEntries, the packConfig view — keys by the pack's
// own id whichever form the file used), `rules` and `accept` are the top-level
// and per-entry settings merged (an entry-sourced acceptance carries
// `pack: <id>` as provenance; conflicting on_fail overrides are a settings
// error), and `packConfig` is the per-pack parameter view, built from each
// entry's `config`. Checks and env machinery
// read this one shape regardless of which form the file used.
export function loadConfig(root) {
  const path = settingsPath(root);
  const empty = { packs: [], packEntries: [], rules: {}, accept: [], sharedConstants: [], packConfig: {}, taskScheduler: null, engineVersion: null, packVersions: {}, dailyClaudiniteUpdatesRequirePrReview: false, raw: null, errors: [] };
  if (!existsSync(path)) return empty;

  let raw;
  try {
    raw = JSON.parse(readFileSync(path, 'utf8'));
  } catch (e) {
    return { ...empty, errors: [{ what: `${SETTINGS_FILE} is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax' }] };
  }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
    return { ...empty, errors: [{ what: `${SETTINGS_FILE} must be a JSON object`, fix: 'wrap the settings in an object: { "packs": [ ... ] }' }] };
  }

  const errors = [];
  for (const key of Object.keys(raw)) {
    if (!KNOWN_CONFIG_KEYS.includes(key)) {
      errors.push({ what: `unknown setting "${key}"`, fix: `remove it or fix the name — valid settings: ${CONFIG_KEYS.join(', ')}` });
    }
  }

  // --- packs: each entry a pack id or { id, config?, rules?, accept?, via? } ---
  const packs = [];
  const packEntries = [];
  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
    if (typeof entry === 'string') {
      packs.push(packEntryId(entry));
      packEntries.push({ id: packEntryId(entry) });
      continue;
    }
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      errors.push({ what: `packs entry ${JSON.stringify(entry)} is neither a pack id nor an entry object`, fix: 'declare a pack as "name" or { "id": "name", ... }' });
      continue;
    }
    if (typeof entry.id !== 'string') {
      errors.push({ what: `packs entry ${JSON.stringify(entry)} has no "id"`, fix: 'give the entry an "id": the pack name' });
      continue;
    }
    for (const key of Object.keys(entry)) {
      if (!PACK_ENTRY_KEYS.includes(key)) {
        errors.push({ what: `unknown property "${key}" on the "${entry.id}" pack entry`, fix: `remove it or fix the name — valid entry properties: ${PACK_ENTRY_KEYS.join(', ')}` });
      }
    }
    const badShape = (prop, expected) =>
      errors.push({ what: `"${prop}" on the "${entry.id}" pack entry must be ${expected}`, fix: `fix or remove the entry's "${prop}"` });
    const normalized = { id: packEntryId(entry) };
    if (entry.version !== undefined) {
      if (isVersion(entry.version)) normalized.version = entry.version;
      else badShape('version', 'the installed pack version — date-anchored <day>.<n>');
    }
    if (entry.config !== undefined) {
      if (entry.config !== null && typeof entry.config === 'object' && !Array.isArray(entry.config)) normalized.config = entry.config;
      else badShape('config', 'an object of the pack\'s parameters');
    }
    if (entry.answers !== undefined) {
      if (entry.answers !== null && typeof entry.answers === 'object' && !Array.isArray(entry.answers)
        && Object.values(entry.answers).every((v) => typeof v === 'string')) normalized.answers = entry.answers;
      else badShape('answers', 'an object mapping the pack\'s question ids to string answers');
    }
    if (entry.rules !== undefined) {
      if (entry.rules !== null && typeof entry.rules === 'object' && !Array.isArray(entry.rules)) normalized.rules = entry.rules;
      else badShape('rules', 'an object of per-rule overrides ("off", "advise" or "block")');
    }
    if (entry.accept !== undefined) {
      if (Array.isArray(entry.accept)) normalized.accept = entry.accept;
      else badShape('accept', 'an array of acceptance entries');
    }
    if (entry.via !== undefined) {
      // Written by the declaration resolver on materialized dependencies
      // (engine/pack_loader/pack-registry.mjs) — normalized through so readers (the adoption
      // interview) can tell a chosen pack from a pulled-in one.
      if (Array.isArray(entry.via) && entry.via.every((v) => typeof v === 'string')) normalized.via = entry.via;
      else badShape('via', 'an array of pack ids (the declaration resolver writes it)');
    }
    packs.push(normalized.id);
    packEntries.push(normalized);
  }

  // --- rules: top-level and per-entry merged; a conflict is a settings error,
  // never a silent last-writer-wins — two packs (or a pack and the top level)
  // disagreeing about a rule's on_fail is a decision the project must make.
  const rules = {};
  const ruleSource = {};
  const mergeRules = (overrides, source) => {
    for (const [ruleId, value] of Object.entries(overrides)) {
      if (ruleId in rules && rules[ruleId] !== value) {
        errors.push({
          what: `rule "${ruleId}" is set to "${rules[ruleId]}" by ${ruleSource[ruleId]} and "${value}" by ${source}`,
          fix: 'make the overrides agree, or keep the rule on one of them',
        });
        continue;
      }
      rules[ruleId] = value;
      ruleSource[ruleId] = source;
    }
  };
  if (raw.rules && typeof raw.rules === 'object') mergeRules(raw.rules, 'the top-level "rules"');
  for (const entry of packEntries) {
    if (entry.rules) mergeRules(entry.rules, `the "${entry.id}" pack entry`);
  }

  // --- accept: top-level entries, then each pack entry's stamped with its
  // provenance (`pack: <id>` — which declaration motivated the exemption).
  const accept = Array.isArray(raw.accept) ? [...raw.accept] : [];
  for (const entry of packEntries) {
    for (const a of entry.accept ?? []) accept.push({ ...a, pack: entry.id });
  }

  // --- packConfig view: per-pack parameters — e.g. the dirs a repo's
  // package.json lives in for the node pack's env install. A derived view keyed by
  // pack id; each entry's own `config` is the one place it is declared.
  const packConfig = {};
  for (const entry of packEntries) {
    if (entry.config !== undefined) packConfig[entry.id] = entry.config;
  }

  // --- taskScheduler: the scheduler's own parameters. Absence is legal, and the
  // value passes through unchanged for the scheduler to read.
  let taskScheduler = null;
  if (raw.taskScheduler !== undefined) {
    if (raw.taskScheduler === null || typeof raw.taskScheduler !== 'object' || Array.isArray(raw.taskScheduler)) {
      errors.push({ what: '"taskScheduler" must be an object', fix: 'e.g. { "disabledTasks": [] }' });
    } else {
      for (const key of Object.keys(raw.taskScheduler)) {
        if (!SCHEDULE_KEYS.includes(key)) {
          errors.push({ what: `unknown "taskScheduler" setting "${key}"`, fix: `remove it or fix the name — valid taskScheduler settings: ${SCHEDULE_KEYS.join(', ')}` });
        }
      }
      // The tasks this repo does not want instantiated (docs/PRINCIPLES.md,
      // "What is not a precondition"). Repo shape — "this repo ships the store
      // pipeline", "this repo has a vendored mount" — is a fact adoption settled,
      // so it is answered once here rather than re-asked by a precondition every
      // night. Validated as a shape only: whether the named task exists is a
      // question about the repo's declared packs, answered where tasks are
      // discovered, and a member may legitimately disable a task it has not
      // adopted yet.
      const { disabledTasks } = raw.taskScheduler;
      if (disabledTasks !== undefined
          && !(Array.isArray(disabledTasks)
            && disabledTasks.every((id) => typeof id === 'string' && /^[^/\s]+\/[^/\s]+$/.test(id)))) {
        errors.push({
          what: `"taskScheduler.disabledTasks" must be an array of "<pack>/<task>" ids, got ${JSON.stringify(disabledTasks)}`,
          fix: 'list the tasks this repo does not run, e.g. ["claudinite-lifecycle/update"]',
        });
      }

      const { dispatch } = raw.taskScheduler;
      const endpoints = raw.taskScheduler[ENDPOINTS_KEY];
      if (dispatch !== undefined && !DISPATCH_MODES.includes(dispatch)) {
        errors.push({
          what: `"taskScheduler.dispatch" must be one of ${DISPATCH_MODES.join(', ')}, got ${JSON.stringify(dispatch)}`,
          fix: 'omit the key — the work-item queue is the only dispatch mechanism; "slots" named the slot scheduler, which is deleted',
        });
      }
      // The endpoint map (docs/PRINCIPLES.md): a name → { url, tokenSecret }.
      // `tokenSecret` is the NAME of a repo Actions secret and never a value —
      // that indirection is the whole reason a task may declare an endpoint at all,
      // since a task declaration is vendored verbatim into every consuming repo.
      if (endpoints !== undefined) {
        if (endpoints === null || typeof endpoints !== 'object' || Array.isArray(endpoints)) {
          errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}" must be an object of endpoint name → { url, tokenSecret }`, fix: 'e.g. { "default": { "url": "https://…", "tokenSecret": "CCR_SESSION_TOKEN" } }' });
        } else {
          for (const [epName, entry] of Object.entries(endpoints)) {
            if (entry === null || typeof entry !== 'object' || Array.isArray(entry)
                || typeof entry.url !== 'string' || typeof entry.tokenSecret !== 'string') {
              errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}.${epName}" must be { url, tokenSecret } (both strings)`, fix: 'give the endpoint an invocation URL and the NAME of the repo Actions secret holding its token — never the token itself' });
            }
          }
        }
      }
      taskScheduler = raw.taskScheduler;
    }
  }

  // --- the installed mount: the engine version this repo holds, and the version of
  // each pack it has installed - the top-level `engineVersion` and each pack entry's
  // own `version`. The retired `claudinite` block that held both was read underneath
  // until #1640; a member still carrying it now reads as having no mount.
  let engineVersion = null;
  if (raw.engineVersion !== undefined) {
    if (isVersion(raw.engineVersion)) engineVersion = raw.engineVersion;
    else {
      errors.push({
        what: `"engineVersion" must be a version — date-anchored <day>.<n>, got ${JSON.stringify(raw.engineVersion)}`,
        fix: 'leave it to the update flows, which write the version they installed',
      });
    }
  }

  const packVersions = {};
  for (const entry of packEntries) {
    if (entry.version !== undefined) packVersions[entry.id] = entry.version;
  }

  // --- the delivery override. `true` is the only value that means anything, so
  // anything else present is a typo the run must not read as "yes" or silently as
  // "no" — a wrong answer here is a PR merged unreviewed on a repo that asked for
  // review, or a repo's daily update stalled forever waiting for a human nobody
  // told.
  let requirePrReview = false;
  if (raw.dailyClaudiniteUpdatesRequirePrReview !== undefined) {
    if (typeof raw.dailyClaudiniteUpdatesRequirePrReview === 'boolean') {
      requirePrReview = raw.dailyClaudiniteUpdatesRequirePrReview;
    } else {
      errors.push({
        what: `"dailyClaudiniteUpdatesRequirePrReview" must be true or false, got ${JSON.stringify(raw.dailyClaudiniteUpdatesRequirePrReview)}`,
        fix: 'set it to true to leave this repo\'s update PR for a human, or remove the key',
      });
    }
  }

  return {
    packs,
    packEntries,
    rules,
    accept,
    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
    packConfig,
    taskScheduler,
    // The installed mount: the top-level `engineVersion` and each entry's own
    // `version`. Omitting a declared key from this returned shape is the worst
    // kind of bug, legal to write and impossible to read: it is what made the
    // stamp invisible to the scheduler and silently killed baselining fleet-wide,
    // every repo self-skipping as "no vendored mount" while its runs went green.
    // The CONFIG_KEYS-survive-loadConfig test pins the whole set.
    engineVersion,
    packVersions,
    // The harsh override, normalized to the boolean every caller asks for and named
    // exactly as the file names it — one spelling, so nothing has to learn that the
    // key and the field it loads into are different words. Absent is the normal
    // shape and means the update PR lands on its own.
    dailyClaudiniteUpdatesRequirePrReview: requirePrReview,
    // The declaration exactly as the member wrote it. The engine normalizes what the
    // engine OWNS; a setting belonging to a pack is that pack's to read, and its
    // reader needs the unnormalized file — both to find a parameter on a pack entry
    // and to resolve a retired top-level spelling the engine deliberately no longer
    // folds. Every caller that has a shape to ask about should ask its owner's
    // predicate, not reach in here.
    raw,
    errors,
  };
}

// One derivation, computed on first read and then remembered. Every work-scoping
// value below costs at least one git subprocess, and a run reads a handful of them:
// a Stop-hook sweep that only judges the session never asks for the merge-base, and
// a test that builds a context for one rule pays for the eight lists that rule never
// looks at. The memo keeps a re-read free, so a rule reading `ctx.files` twice still
// spawns `check-attr` once — exactly what the eager field did.
// Derive once, on first read. The flag is set AFTER the call, not before: a
// derivation that throws must throw again on the next read rather than be
// remembered as `undefined`, which is what the eager form did — it threw during
// buildContext and the run stopped there.
const once = (fn) => {
  let value, derived = false;
  return () => {
    if (!derived) { value = fn(); derived = true; }
    return value;
  };
};

// Replace a lazy accessor with a plain value assigned over it. ESM is strict, so a
// getter with no setter turns `ctx.files = …` into a TypeError. Nothing in this repo
// assigns to one, but the engine is vendored into member repos whose own local packs
// this canon cannot see; the setter keeps such an assignment behaving exactly as it
// did against the eager data property instead of crashing that member's sweep.
const overwrite = (ctx, key, value) =>
  Object.defineProperty(ctx, key, { value, writable: true, enumerable: true, configurable: true });

export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
  root = resolve(root);
  // The base ref and its refresh are the one pair that stays eager. Building a
  // context is what makes the base branch current — that is the refresh's whole
  // contract, and a caller that discards the context still wanted it done. Making it
  // a side effect of reading `ctx.mergeBase` would move that contract instead of
  // deferring a cost.
  const baseRef = baseOverride || resolveBaseRef(root);
  refreshBaseRef(root, baseRef);
  const mergeBase = once(() => (baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null));
  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
  const diffBase = () => mergeBase() || 'HEAD';
  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
  // be on it, so nothing is filtered out.
  const onBaseBranch = (sha) =>
    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;

  // The vendored corpus under the shared mount is canon-owned, never the
  // project's own code — structurally out of scope for every check, on any git
  // host and any checkout (deliberately not attribute-driven). The consumer's
  // own .claudinite/local/packs/ sits BESIDE the shared mount and stays fully
  // in scope.
  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
  // with the platform separator, so normalize before prefix-matching.
  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;

  const { tracked, untracked } = listFiles(root);
  // Both diff lists come out of the one call, so whichever is read first pays for the
  // pair — as the eager form did.
  const diff = once(() => diffLists(root, diffBase(), mergeBase()));
  const vsBase = () => diff().vsBase;
  const deleted = () => diff().deleted;
  const scanned = once(() => (mode === 'all'
    ? [...tracked, ...untracked]
    : [...new Set([...vsBase(), ...untracked])]).filter((f) => !f.startsWith(sharedPrefix)));
  // Every in-scope regular file, vendored/generated included.
  const allFiles = once(() => scanned().filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile()));
  // The default sweep excludes vendored/generated files, so `ctx.files` is the
  // project's OWN authored code and every check skips them for free (see vendoredSet).
  const files = once(() => {
    const vendored = vendoredSet(root, allFiles());
    return allFiles().filter((f) => !vendored.has(f));
  });
  // The in-scope files the current change touched (vs the scoping base),
  // untracked included — the file set behind lines.mjs addedLines, for
  // check-the-work rules that judge the work rather than re-audit the world.
  const changedFiles = once(() => {
    const changedSet = new Set([...vsBase(), ...untracked]);
    return files().filter((f) => changedSet.has(f));
  });

  const commits = once(() => {
    if (!mergeBase()) return [];
    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase()}..HEAD`);
    return (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
  });

  const branch = once(() => (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim());

  // Conversation surface: the Stop hook forwards the session's transcript_path;
  // every other surface (CI, a manual run) has none, and conversation rules must
  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
  let conversationCache;
  let sessionEntriesCache;

  // Checks are read-only over an immutable snapshot of the tree, so file and
  // base-blob reads are cached for the sweep: many rules re-read the same files,
  // and each readBase is otherwise a git subprocess.
  const readCache = new Map();
  const readBaseCache = new Map();

  // The work-scoping fields are accessors over the memos above; `root`, `mode`,
  // `baseRef`, `tracked`, `untracked` and `config` stay plain values, being either
  // free or read by nearly every rule. Declaring each accessor in place keeps the
  // key order — and so `Object.keys`, a spread and `JSON.stringify` — what it was.
  return {
    root,
    mode,
    baseRef,
    get mergeBase() { return mergeBase(); },
    set mergeBase(v) { overwrite(this, 'mergeBase', v); },
    get files() { return files(); },
    set files(v) { overwrite(this, 'files', v); },
    get allFiles() { return allFiles(); },
    set allFiles(v) { overwrite(this, 'allFiles', v); },
    get changedFiles() { return changedFiles(); },
    set changedFiles(v) { overwrite(this, 'changedFiles', v); },
    tracked,
    untracked,
    get deleted() { return deleted(); },
    set deleted(v) { overwrite(this, 'deleted', v); },
    get commits() { return commits(); },
    set commits(v) { overwrite(this, 'commits', v); },
    get branch() { return branch(); },
    set branch(v) { overwrite(this, 'branch', v); },
    config: loadConfig(root),

    exists: (path) => existsSync(join(root, path)),
    read(path) {
      if (!readCache.has(path)) {
        let text;
        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
        readCache.set(path, text);
      }
      return readCache.get(path);
    },

    // File content at the scoping base (the merge-base with the base branch), or
    // null if the file didn't exist there or no base resolves. Lets a delta
    // check compare structured state — e.g. a manifest's permission set — against
    // the baseline precisely, immune to text-diff line noise (JSON trailing
    // commas make appending an array element re-touch the previous line).
    readBase(path) {
      if (!mergeBase()) return null;
      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase()}:${path}`));
      return readBaseCache.get(path);
    },

    // Added lines of one file relative to the scoping base (untracked file = every line).
    addedLines(file) {
      if (!tracked.includes(file)) {
        const text = this.read(file);
        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
      }
      const out = gitTry(root, 'diff', '-U0', diffBase(), '--', file);
      const added = [];
      let lineNo = 0;
      for (const l of (out || '').split('\n')) {
        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
        if (hunk) { lineNo = Number(hunk[1]); continue; }
        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
      }
      return added;
    },

    // The lines the change REMOVES from a tracked file, numbered as the base
    // had them — the diff's "-" side, the mirror of addedLines. A file the
    // base did not hold removed nothing.
    removedLines(file) {
      if (!mergeBase() || !tracked.includes(file)) return [];
      const out = gitTry(root, 'diff', '-U0', diffBase(), '--', file);
      const removed = [];
      let lineNo = 0;
      for (const l of (out || '').split('\n')) {
        const hunk = /^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/.exec(l);
        if (hunk) { lineNo = Number(hunk[1]); continue; }
        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
      }
      return removed;
    },

    // Parsed transcript entries of the session driving this run, or null when no
    // transcript is available (see conversationCache above).
    conversation() {
      if (conversationCache !== undefined) return conversationCache;
      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
      catch { conversationCache = null; }
      return conversationCache;
    },

    // Every entry the session wrote — the transcript above plus each subagent
    // stream beside it — for the rules that judge what the session DID: the
    // skills it loaded, the calls it made. `conversation()` stays the session
    // file alone, since that is where the owner's turns are. Empty on a surface
    // with no transcript, which `conversation()` is what distinguishes from a
    // session that did nothing.
    sessionEntries() {
      if (sessionEntriesCache === undefined) {
        sessionEntriesCache = sessionTranscriptPaths(transcriptPath).flatMap((path) => {
          // A stream unreadable mid-write costs its own entries, never the others'.
          try { return parseEntries(readFileSync(path, 'utf8')); } catch { return []; }
        });
      }
      return sessionEntriesCache;
    },

    // The branch's own commits since the merge-base, oldest first, each with its
    // changed files and committer date — for rules about the ORDER work landed in
    // (ctx.commits keeps only messages). Merges excluded: their file list is
    // empty under --name-only and their content arrives via their parents.
    commitsWithFiles() {
      if (!mergeBase()) return [];
      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase()}..HEAD`);
      const parsed = [];
      for (const block of (out || '').split('\0')) {
        if (!block.trim()) continue;
        const [head, ...rest] = block.trim().split('\n');
        const [sha, date, subject] = head.split('\x1f');
        parsed.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
      }
      return parsed;
    },

    // Merge commits the current change introduces — those on HEAD's first-parent
    // chain since the merge-base with the base branch (the squash-only effect
    // check, scoped to the work). Empty when no base resolves or the branch is
    // even with it; pre-existing merges already on the base are out of range.
    //
    // The range alone trusts the merge-base to be right, and it isn't always: a
    // shallow clone's grafted boundary or a criss-cross history can hand back a
    // merge-base that sweeps the base branch's own merges into the range. So each
    // candidate is confirmed against the base ref itself — a merge already on the
    // base branch was never introduced here, whatever the range says. Offline and
    // exact, and it holds when refreshBaseRef couldn't run.
    introducedMergeCommits() {
      if (!mergeBase()) return [];
      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase()}..HEAD`);
      return lines(out).map((l) => {
        const i = l.indexOf(' ');
        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
      }).filter(({ sha }) => !onBaseBranch(sha));
    },

    // Fixed-string search across tracked files; git grep exits 1 on no match.
    // The vendored shared mount is structurally out of the sweep (canon-owned,
    // never the project's own code — vendoring/DESIGN.md item 6), so it is
    // excluded here exactly as it is from the scanned file set above: a hit
    // inside it must never become a finding.
    grepTracked(needle) {
      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
      return lines(out).map((l) => {
        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
      }).filter(Boolean);
    },
  };
}

export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));

