=== chrome-extension ===
import { findExtensionManifest } from '../../engine/checks/helpers/chrome-manifest.mjs';

// Everything about a Chrome extension in one pack: the MV3 build/runtime gotchas
// that apply while you are writing one, and the Chrome-Web-Store release standard
// that applies once you publish it. Fingerprinted by the manifest, which is what a
// repo has from its first commit.
//
// THE RELEASE HALF IS GATED ON SHIPPING, not on a second declaration (#1057). It
// used to be its own opt-in pack, chrome-extension-release, whose `detect` was the
// orchestrator workflow's name — so the fact that decided whether the release rules
// applied was always structural, and the declaration was a second copy of it that a
// repo had to remember to write. Now that fact is read where it is used:
// `shipsReleasePipeline` gates the coded rule, and every declared check carries the
// same test as its `relevantWhen`. A repo that only codes an extension sees none of
// them; a repo that publishes gets them without anyone declaring anything.
//
// The `cer/` check ids are kept as they are. A member's `accept` entries name rules
// by id, and renaming one silently orphans an acceptance — the finding comes back
// with nothing to carry the member across. A prefix outliving the pack it was named
// for is the cheaper of those two.
// The release standard itself — the pipeline's contract, the setup for a new
// extension repo, and the store steps no automation can take — is skills/, not
// prose: it is long, and only the checks need to be eager.
export default {
  version: '60925.2',
  minEngineVersion: '60925.1',
  ruleRoutingGuidance: {
    belongs: 'writing and shipping a Chrome extension: MV3 service-worker, permission, content-script and auth gotchas, plus Web Store release, versioning and privacy',
    excludes: 'generic workflow lint rules — git-github; shipping to a different store — the app-store-release and play-store-release packs',
  },
  marker: 'a manifest.json declaring manifest_version',
  detect: (ctx) => findExtensionManifest(ctx) !== null,
  // Delivery, not state: the tree always carries a version, and only the diff
  // says whether it moved with the shipped files beside it.
  // Pack-contributed task: `tasks/store-release/` — the scheduler's filesystem scan
  // (packs/claudinite-tasks/discover.mjs) picks it up on any repo declaring this pack, so
  // its own precondition is what keeps it off a repo that does not publish.
};

=== headless-browser ===
// The headless-browser pack: driving a real browser from your own process —
// resolving and pinning the build, replacing everything about the page's world
// that would otherwise vary, and the capture mechanics. Prose only, and
// fingerprinted by a driver reference in JS/TS source: the module specifier of a
// browser-automation package, or a `.launch(` call site.

const DRIVER_MODULE = /['"](playwright(?:-core)?|puppeteer(?:-core)?)['"]/;
const LAUNCH_CALL = /\b(?:chromium|firefox|webkit|puppeteer)\.launch\s*\(/;
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx)$/;

export default {
  version: '60925.1',
  minEngineVersion: '60925.1',
  ruleRoutingGuidance: {
    belongs:
      'driving a real browser from code — resolving and pinning the build, faking the page world, capture mechanics',
    excludes:
      'which engine a UI golden needs and its review gate — basics writing-tests; workflow wiring — git-github',
  },
  marker: 'a browser-automation driver (playwright / puppeteer, or a .launch( call) referenced in JS/TS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (DRIVER_MODULE.test(text) || LAUNCH_CALL.test(text));
    }),
};

=== jwt ===
// The JSON Web Token pack: minting and validating JWTs safely. It contributes
// no prose; two action skills (jwt-minting, jwt-validation) carry the judgment
// half, and five declared checks under them carry the static half.
//
// Fingerprinted by a JWT library reference in JS/TS/Python source. The marker
// only *suspects* the pack; declaring it is the project's call, like every pack.
const JWT_LIB = /['"](jsonwebtoken|express-jwt|jwks-rsa|node-jose|jose|python-jose)['"]|^\s*(import\s+jwt\b|from\s+jwt(\.[\w.]*)?\s+import\b)/m;
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx|py)$/;

export default {
  version: '60925.1',
  minEngineVersion: '60925.1',
  ruleRoutingGuidance: {
    belongs: 'minting and validating JSON Web Tokens: algorithm pinning, claim validation, key strength and secrecy, expiry, JWE',
    excludes: 'the Google-issuer validator config — google-identity; OAuth client-side token acquisition — chrome-extension',
  },
  marker: 'a JWT library (jsonwebtoken / jose / PyJWT) referenced in JS/TS/Python source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && JWT_LIB.test(text);
    }),
};

=== leaflet ===

// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
// Leaflet.markercluster).

const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;

export default {
  version: '60925.1',
  minEngineVersion: '60925.1',
  ruleRoutingGuidance: {
    belongs: 'map rendering with the Leaflet library — map init options, tile layers, markers and divIcons, CDN plugin pinning',
    excludes: 'generic HTML markup rules — that is html; non-map dependency policy belongs to node',
  },
  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
    }),
};

=== web-speech ===
// The browser voice-I/O pack: speech-to-text (webkitSpeechRecognition / the Web
// Speech SpeechRecognition API) and text-to-speech (chrome.tts / speechSynthesis)
// runtime gotchas that apply whenever an app reads or listens through the browser.
// Mostly prose, with the call-site contracts in worldRules/, the web-speech-io
// skill's rules and the voice-cache declaration beside this file as checks.
// Fingerprinted by an actual speech-API reference in JS/TS source.
const SPEECH_API =
